  function handoff(){return typeof handoffFor==='function'?handoffFor(B,review,{statusFor:decisionStatus}):{project:B.project,entries:B.entries,annotations:(uiMode==='compare'||!$('show-pins').checked?[]:review.annotations).map(a=>({...a,stale:a.target?.kind==='region'&&a.target.visibleStateHashAtCreation&&a.target.visibleStateHashAtCreation!==visibleStateHash(B,review,a.target.entry)})),decisions:review.decisions,deleted,previewEdits:review.previewEdits,unresolved};}
