  $('import-file').onchange=async()=>{importCandidate=null;$('apply-import').disabled=true;$('import-preview').replaceChildren();try{const file=$('import-file').files[0];if(!file||file.size>100*1024*1024)throw Error('크기 제한 초과');const incoming=JSON.parse(await file.text());if(incoming.bundleHash!==B.bundleHash||incoming.reviewId!==B.reviewId)throw Error('다른 bundle: 검증된 previousBundle을 이용한 CLI rebase 필요');if(typeof validateState==='function')validateState(B,incoming);importCandidate=incoming;const result=mergeState(B,review,incoming,{}),root=$('import-preview');root.replaceChildren();for(const conflict of result.conflicts||[]){const label=document.createElement('label');label.textContent=JSON.stringify(conflict);const select=document.createElement('select');select.dataset.conflict=conflict.key||conflict.collection+':'+conflict.id;select.add(new Option('현재 유지','current'));select.add(new Option('가져온 값','incoming'));label.append(select);root.append(label);}const p=document.createElement('p');p.textContent=`가져오기 미리보기 · 의견 ${incoming.annotations?.length||0}, 삭제 ${incoming.deleted?.length||0}, 충돌 ${result.conflicts?.length||0}`;root.prepend(p);$('apply-import').disabled=false;}catch(error){$('status').textContent='가져오기 거절 · '+error.message;}};
  $('cancel-import').onclick=()=>{importCandidate=null;$('apply-import').disabled=true;$('import-preview').replaceChildren();$('import-file').value='';$('status').textContent='가져오기 취소 · 현재 검토 유지';};
  $('apply-import').onclick=()=>{if(!importCandidate)return;const choices={};for(const select of $('import-preview').querySelectorAll('select'))choices[select.dataset.conflict]=select.value;try{const result=mergeState(B,review,importCandidate,choices);if(result.conflicts?.length)throw Error('충돌 선택 필요');checkpoint();review=result.state;deleted=review.deleted;unresolved=review.unresolved;importCandidate=null;$('apply-import').disabled=true;renderReview();renderDeletions();notifyState();}catch(error){$('status').textContent=error.message;}};
  async function rasterExport(overlay){const side=target?.side||selection?.side||'before',entry=active[side],tile=entry.tiles?.find(t=>t.id===$('tile').value)||entry.tiles?.[0],comparison=B.comparisons?.find(c=>c.entry===active.id),asset=tile?.image||comparison?.[side==='before'?'beforeAsset':'afterAsset'];if(!asset){$('status').textContent='원본 raster 미확보 · 현재 DOM PNG는 안내된 로컬 명령 사용';return;}const img=new Image();img.src=B.assets[asset].data;await img.decode();const rect=target?.kind==='region'?target.rect:tile?.rects?.find(r=>r.id===(target?.elementId||selection?.id))?.rect,scale=img.width/(tile?.width||B.viewports.find(v=>v.id===active.viewport).width),r=rect?rect.map(v=>v*scale):[0,0,img.width,img.height],canvas=document.createElement('canvas');canvas.width=r[2];canvas.height=r[3];const ctx=canvas.getContext('2d');ctx.drawImage(img,r[0],r[1],r[2],r[3],0,0,r[2],r[3]);if(overlay){for(const a of review.annotations.filter(a=>a.target?.entry===active.id&&a.target.side===side)){const q=a.target.rect||tile?.rects?.find(t=>t.id===a.target.elementId)?.rect;if(!q)continue;ctx.strokeStyle='#d83b2e';ctx.lineWidth=2*scale;ctx.strokeRect(q[0]*scale-r[0],q[1]*scale-r[1],q[2]*scale,q[3]*scale);ctx.fillStyle='#d83b2e';ctx.font=`${14*scale}px sans-serif`;ctx.fillText(a.priority+' '+a.text.slice(0,50),q[0]*scale-r[0],Math.max(16*scale,q[1]*scale-r[1]));}}canvas.toBlob(blob=>{if(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${active.id}-${side}-${entry.revision}-${overlay?'annotations':'original'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}},'image/png');}
  $('export-comparison').onclick=async()=>{const c=B.comparisons?.find(c=>c.entry===active.id&&(!c.tile||c.tile===$('tile').value));if(!c?.compatible){$('status').textContent=c?.reason||'동일 조건 원본 raster 미확보';return;}const images=await Promise.all([c.beforeAsset,c.afterAsset,c.diffAsset].map(async id=>{if(!id)return null;const image=new Image();image.src=B.assets[id].data;await image.decode();return image;})),mode=$('comparison').value,canvas=document.createElement('canvas');canvas.width=images[0].width*(mode==='both'?2:1);canvas.height=images[0].height;const ctx=canvas.getContext('2d');ctx.drawImage(mode==='diff'?images[2]:mode==='after'?images[1]:images[0],0,0);if(mode==='both')ctx.drawImage(images[1],images[0].width,0);if(mode==='overlay'){ctx.globalAlpha=$('compare-range').value/100;ctx.drawImage(images[1],0,0);}if(mode==='wipe'){ctx.save();ctx.beginPath();ctx.rect(0,0,images[0].width*$('compare-range').value/100,images[0].height);ctx.clip();ctx.drawImage(images[1],0,0);ctx.restore();}canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=active.id+'-original-'+mode+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);},'image/png');};
  $('export-png').onclick=()=>rasterExport(false);$('export-overlay').onclick=()=>rasterExport(true);
  window.addEventListener('beforeunload',event=>{if(dirty||patchDrafts.size){event.preventDefault();event.returnValue='';}});
  document.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const root=$('navigator').classList.contains('open')?$('navigator'):innerWidth<1200&&!$('inspector').hidden?$('inspector'):null;if(!root)return;const items=[...root.querySelectorAll('button,input,select,textarea,summary,a[href],[tabindex]')].filter(el=>!el.disabled&&el.getClientRects().length&&el.tabIndex>=0);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||!root.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!root.contains(document.activeElement))){event.preventDefault();first.focus();}},true);
  document.addEventListener('keydown',event=>{if(event.isComposing)return;if(event.key==='Escape'){if($('navigator').classList.contains('open')){closeNavigator();$('toggle-navigator').focus();}else if(!$('inspector').hidden){closeInspector();$(uiMode==='advanced'?'toggle-inspector':'mode-simple').focus();}else{$('find-element').open=false;}return;}if(event.target.closest('input,textarea,select,[contenteditable]'))return;if(uiMode!=='compare'&&(event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();undo(event.shiftKey);}});



  function notes(){const root=$('notes');const add=(title,value)=>{const h=document.createElement('h3'),p=document.createElement('pre');h.textContent=title;p.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);root.append(h,p);};add('브랜드',B.brand);add('검토 범위',B.coverage);if(!B.research.length)add('디자인 근거','참고 조사 없음 · 기능 예시 또는 조사 미완료');for(const r of B.research){add(r.title||'참고 디자인',r);if(/^https?:\/\//.test(r.url)){const a=document.createElement('a');a.textContent='출처 열기';a.href=r.url;a.target='_blank';a.rel='noreferrer';root.append(a);}}}
  if(innerWidth<768)$('comparison').value='after';notes();render();renderReview();
