  window.uibExportEntry=id=>{const e=B.entries.find(e=>e.id===id);if(!e)throw Error('Unknown entry');active=e;$('view-state').value='current';$('zoom').value='actual';$('comparison').value='after';render();$('after-frame').dataset.exportSide='after';};window.uibExportReady=()=>!!$('after-frame').contentWindow;
  window.uibSnapshot=()=>({entry:active.id,deleted:[...deleted],unresolved:[...unresolved],uiMode,selection:selection?.id||null,indexHash:B.indexHash,state:structuredClone(review),target,selected:uiMode==='compare'?[]:[...selectedIds],dirty});
